import{z as n,x as A,o,c,q as l,j as B,D as E,d as t,s as i,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"LSM 的深入","description":"","frontmatter":{"title":"LSM 的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/st-lsm-deep.md","filePath":"cs/st-lsm-deep.md","lastUpdated":1791063341000}'),d={name:"cs/st-lsm-deep.md"};function p(m,a,C,D,L,F){const s=A("Mermaid");return o(),c("div",null,[a[2]||(a[2]=l('<h1 id="lsm-的深入" tabindex="-1">LSM 的深入 <a class="header-anchor" href="#lsm-的深入" aria-label="Permalink to &quot;LSM 的深入&quot;">​</a></h1><div class="epigraph"><p>LSM 用顺序写换随机写的报价不是一次付清：每层归并都把同一批字节重写一遍，深入是读完这份报价单的细则。</p><footer>—— 据 O&#39;Neil et al., 1996；Lu et al., WiscKey, FAST 2016；RocksDB 文档整理</footer></div><p><a href="/cs/hpc-map">上一课</a>把高性能网络的账收束在「每下移一层，就把每次都付的固定税改写成一次付清的固定成本」，并留下测量纪律先于优化的结论。本课是「存储系统深入」的第一课，回到磁盘上的结构：主干已经钉过 <a href="/cs/lsm-tree-ds">LSM 树作为结构</a>的内存表加不可变有序段、<a href="/cs/lsm-compaction">compaction</a> 的顺序刷盘与持续税、<a href="/cs/lsm-read-amplification">读放大与布隆</a>的过滤、<a href="/cs/leveled-tiered-compaction">leveled 对 tiered</a> 的形状合同，以及 <a href="/cs/rocksdb">RocksDB</a> 把这一切变成选项名。本课不再比较形状，而是立三本放大的总账，回答工程里真正卡住人的三个问题：写放大的预算怎么算、写停顿为什么是流控而不是故障、把值从 LSM 里搬出去为什么几乎全面变好。后课默认这三本账已经立起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干课给了方向：leveled 写重读轻、tiered 相反。深入要的是数。缺口一，放大的预算式核算：写放大 WAF（落盘字节除以逻辑写入字节）、读放大、空间放大各是多少量级，怎么折成带宽与容量规划——持续写 100 MB/s、WAF 为 20 的系统，compaction 带宽必须按 2 GB/s 起步去规划，否则顺序读 3 GB/s 的盘也会被拖垮。缺口二，写停顿：compaction 跟不上时写被延迟甚至拒绝，这是机制还是故障。缺口三，值的问题：排序只对键有意义，值却占字节大头，跟着键一层层重写——WiscKey 问的就是这个字节交得冤不冤。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先立账。写放大的机制账这样算：在层间比值为 \\(T\\) 的 leveled 形状里，第 \\(i\\) 层并入第 \\(i+1\\) 层时要重写本层数据加下一层的重叠区间，摊到每次刷盘约是 memtable 的 \\(T\\) 倍，\\(L\\) 层合计最坏在 \\(T\\cdot L\\) 量级，其中 \\(L=\\log_T(N/T)\\)；tiered 每层只摊一份，写放大约是层数，但同层 \\(T\\) 个重叠文件把点查读放大抬到 \\(T\\cdot L\\)。<span class="marginnote">数字实例：业务持续写 100 MB/s、WAF 为 20 时，盘上实际要落盘 2 GB/s——一块顺序写 3 GB/s 的盘只剩 1 GB/s 给读。先做这道乘法，再谈盘型选型。</span>两端的量级差就是形状课主曲线的具体数字。</p><p>写停顿按流控读：memtable 满而 L0 到 L1 没有槽位时，刷盘阻塞，写入在内存里堆积，系统先延迟（软限）后拒绝（硬限）。此时 pending compaction bytes 是债务：读这个数比读延迟分布更早知道故障。<span class="marginnote">直觉类比：写停顿像信用卡还款——每期只还最低额，利息照滚。compaction 跟不上先给你延期宽限（软限），债滚到额度顶（硬限）就直接拒收；pending compaction bytes 就是账单余额。</span>停顿不是 bug 而是背压——不停顿，归并债务按指数滚，最后一次性以分钟级停顿结清。</p><p>值的出路是分离：键小而需要有序，留在 LSM 里保点查与范围扫描；值大而不需要顺序，进一个只追加的 value log，键里只存偏移。点查变两步：查 LSM 拿偏移，再读一次值。范围扫描要先按偏移排序再成批顺序读。GC 搬活值回收空间，与 compaction 同构。</p>',9)),(o(),B(r,null,{default:E(()=>[i(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUT%5B%22%E5%86%99%E5%85%A5%20KV%22%5D%20--%3E%20SEP%7B%22%E9%94%AE%E5%80%BC%E5%88%86%E7%A6%BB%22%7D%0A%20%20SEP%20--%3E%7C%22%E9%94%AE%22%7C%20LSM%5B%22memtable%20%E2%86%92%20L0%20%E2%86%92%20%E9%80%90%E5%B1%82%E5%BD%92%E5%B9%B6%22%5D%0A%20%20SEP%20--%3E%7C%22%E5%80%BC%22%7C%20VLOG%5B%22value%20log%20%E8%BF%BD%E5%8A%A0%22%5D%0A%20%20LSM%20--%3E%20OFF%5B%22%E9%94%AE%E4%B8%AD%E5%AD%98%20vLog%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20OFF%20--%3E%20GET%5B%22%E7%82%B9%E6%9F%A5%EF%BC%9A%E6%9F%A5%20LSM%20%E5%90%8E%E8%AF%BB%20vLog%22%5D%0A%20%20VLOG%20--%3E%20GC%5B%22GC%20%E6%90%AC%E6%B4%BB%E5%80%BC%E5%9B%9E%E6%94%B6%E7%A9%BA%E9%97%B4%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"分离有效的机制在于成本与收益错位：归并重写按字节计费，有序性只按键维护。一个 1 KiB 的值配 100 B 的键，值贡献了九成字节却对排序毫无贡献，却要在写放大 \\(T\\cdot L\\) 的账单里按同样倍数被重写。摘出去之后，值的写放大从「跟着键走 \\(L\\) 层」降到「只写一次加 GC 摊销」，三本账同时改善，唯独范围扫描付出按偏移重排的代价——这也是分离方案只在点查为主的负载上稳赚的原因。",-1)),a[5]||(a[5]=e("p",null,[t("空间放大与写放大同构：旧版本和墓碑靠归并回收，快照把读序列号钉住，compaction 就不敢丢被它看见的版本。一个被遗忘的长快照能让 SAF 静默翻倍，病根与 MVCC 的长事务相同。GC 与 compaction 是同一个思想在 vLog 与 LSM 里的两个名字：搬运活数据、丢弃死数据、付写放大。"),e("span",{class:"marginnote"},"常见误区：以为空间悄悄翻倍是 compaction 配置不对。常见病根其实是一个被遗忘的长生命周期快照把旧版本钉住，compaction 不敢回收——先查快照与长事务，再动参数。")],-1)),(o(),B(r,null,{default:E(()=>[i(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUT%5B%22%E5%86%99%E5%85%A5%E6%8C%81%E7%BB%AD%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20MEM%7B%22memtable%20%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20MEM%20--%3E%7C%22%E5%90%A6%22%7C%20W%5B%22%E5%86%99%E5%85%A5%E6%88%90%E5%8A%9F%22%5D%0A%20%20MEM%20--%3E%7C%22%E6%98%AF%22%7C%20FLUSH%5B%22%E5%88%B7%E4%B8%BA%20L0%20%E6%96%87%E4%BB%B6%22%5D%0A%20%20FLUSH%20--%3E%20SLOT%7B%22L0%20%E5%88%B0%20L1%20%E6%9C%89%E6%A7%BD%E4%BD%8D%EF%BC%9F%22%7D%0A%20%20SLOT%20--%3E%7C%22%E6%98%AF%22%7C%20COMP%5B%22%E6%AD%A3%E5%B8%B8%E5%BD%92%E5%B9%B6%EF%BC%8C%E5%80%BA%E5%8A%A1%E6%B8%85%E5%81%BF%22%5D%0A%20%20SLOT%20--%3E%7C%22%E5%90%A6%22%7C%20STALL%5B%22%E5%86%99%E5%85%A5%E5%BB%B6%E8%BF%9F%EF%BC%9A%E8%BD%AF%E9%99%90%E8%83%8C%E5%8E%8B%22%5D%0A%20%20STALL%20--%3E%20HARD%7B%22%E5%80%BA%E5%8A%A1%E8%B6%85%E7%A1%AC%E9%99%90%EF%BC%9F%22%7D%0A%20%20HARD%20--%3E%7C%22%E6%98%AF%22%7C%20REJECT%5B%22%E5%86%99%E5%85%A5%E8%A2%AB%E6%8B%92%E7%BB%9D%22%5D%0A%20%20HARD%20--%3E%7C%22%E5%90%A6%22%7C%20LOOP%5B%22%E7%BB%A7%E7%BB%AD%E7%AD%89%E5%BE%85%E5%BD%92%E5%B9%B6%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">量级锚点：\\(T=10\\)、四层数据时，leveled 写放大最坏在 \\(T\\cdot L\\approx 40\\) 的量级，常见实测 10–30；预算式核算是「持续写入带宽乘 WAF 等于 compaction 所需带宽」，先有这道乘法再谈盘型选型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重比 leveled 与 tiered 的放大公式（<a href="/cs/leveled-tiered-compaction">形状课</a>已钉），不展开 RocksDB 的调参清单（<a href="/cs/rocksdb">嵌入式合同</a>已给），不进分布式复制；数字是量级锚点而非实测承诺，上盘前按网络课程留下的纪律先测自己的负载。后课默认：写入放大是要做预算的账，排序是有成本的决策。下一课看另一族结构怎么在同样的页 I/O 账上签字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三本账先立预算：WAF、读放大、SAF；compaction 带宽按 WAF 乘持续写入带宽规划。</li><li>写停顿是流控不是故障：pending compaction bytes 是债务，比延迟更早报警。</li><li>WiscKey 把值摘出排序机：值只写一次，范围扫描付按偏移重排的代价。</li><li>空间放大来自旧版本与墓碑；长快照钉住回收，与 MVCC 长事务同病。</li><li>出处：O&#39;Neil et al., 1996；Lu et al., WiscKey, FAST 2016；Dayan and Idreos, PVLDB 2018；RocksDB 文档。</li></ul>',5))])}const h=n(d,[["render",p]]);export{T as __pageData,h as default};
